
PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT UNIQUE,password_hash TEXT,role TEXT NOT NULL CHECK(role IN ('customer','admin','merchant','rider')),name TEXT NOT NULL,shop_id TEXT,online INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS shops(id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,address TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',lat REAL,lng REAL,image_url TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT 'survey',source_id TEXT UNIQUE,source_url TEXT NOT NULL DEFAULT '',verification TEXT NOT NULL DEFAULT 'unverified' CHECK(verification IN ('unverified','verified')),verified_at TEXT,verified_by TEXT REFERENCES users(id),survey_note TEXT NOT NULL DEFAULT '',opt_in INTEGER NOT NULL DEFAULT 0,accepting INTEGER NOT NULL DEFAULT 0,order_mode TEXT NOT NULL DEFAULT 'rider_purchase' CHECK(order_mode IN ('rider_purchase','merchant_confirm')),updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS menus(id TEXT PRIMARY KEY,shop_id TEXT NOT NULL REFERENCES shops(id),name TEXT NOT NULL,price_satang INTEGER NOT NULL CHECK(price_satang>=0),image_url TEXT NOT NULL DEFAULT '',available INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES users(id),shop_id TEXT REFERENCES shops(id),rider_id TEXT REFERENCES users(id),status TEXT NOT NULL CHECK(status IN ('waiting','ready','assigned','picked','done','cancelled')),kind TEXT NOT NULL DEFAULT 'food',snapshot TEXT NOT NULL,pickup TEXT NOT NULL,dropoff TEXT NOT NULL,customer_name TEXT NOT NULL,phone TEXT NOT NULL,lat REAL,lng REAL,note TEXT NOT NULL DEFAULT '',image TEXT NOT NULL DEFAULT '',inside_image TEXT NOT NULL DEFAULT '',goods_satang INTEGER NOT NULL,fee_satang INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,idempotency_key TEXT NOT NULL,UNIQUE(customer_id,idempotency_key));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_job_per_rider ON orders(rider_id) WHERE status IN ('assigned','picked');
CREATE INDEX IF NOT EXISTS orders_customer ON orders(customer_id,created_at);
CREATE INDEX IF NOT EXISTS orders_queue ON orders(status,created_at);
CREATE TABLE IF NOT EXISTS order_events(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id TEXT NOT NULL REFERENCES orders(id),actor_id TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,target TEXT NOT NULL,created_at TEXT NOT NULL);
